begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values
 ('00000000-0000-0000-0000-00000000a401','date-a@example.com'),
 ('00000000-0000-0000-0000-00000000b401','date-b@example.com'),
 ('00000000-0000-0000-0000-00000000c401','date-c@example.com');
insert into friendships(requester_id,addressee_id,status) values
 ('00000000-0000-0000-0000-00000000a401','00000000-0000-0000-0000-00000000b401','accepted');
select ok((select relrowsecurity from pg_class where oid='public.focus_dates'::regclass),'dates enforce RLS');
select ok(not has_table_privilege('anon','public.focus_dates','SELECT'),'anonymous cannot read dates');
select ok(not has_table_privilege('authenticated','public.focus_dates','INSERT'),'no direct insert');
select ok(not has_table_privilege('authenticated','public.focus_dates','UPDATE'),'no direct update');
select ok(not has_table_privilege('authenticated','public.focus_dates','DELETE'),'no direct deletion');
select ok(not has_function_privilege('anon','public.propose_focus_date(uuid,uuid,timestamptz)','EXECUTE'),'anonymous cannot propose');
select ok(not has_function_privilege('anon','public.respond_focus_date(uuid,bigint,text)','EXECUTE'),'anonymous cannot respond');
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='public.propose_focus_date(uuid,uuid,timestamptz)'::regprocedure),'proposal search path pinned');
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='public.respond_focus_date(uuid,bigint,text)'::regprocedure),'response search path pinned');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000a401',true);
select throws_ok($$select propose_focus_date(gen_random_uuid(),'00000000-0000-0000-0000-00000000a401',now()+interval '1 day')$$,'22023','Invalid focus date','cannot invite self');
select throws_ok($$select propose_focus_date(gen_random_uuid(),'00000000-0000-0000-0000-00000000c401',now()+interval '1 day')$$,'P0002','Friend unavailable','non-friend unavailable');
select throws_ok($$select propose_focus_date(gen_random_uuid(),'00000000-0000-0000-0000-00000000b401',now()-interval '1 minute')$$,'22023','Choose a future time within 90 days','past rejected');
select throws_ok($$select propose_focus_date(gen_random_uuid(),'00000000-0000-0000-0000-00000000b401',now()+interval '91 days')$$,'22023','Choose a future time within 90 days','bounds future');
select throws_ok($$select propose_focus_date(gen_random_uuid(),'00000000-0000-0000-0000-00000000b401','infinity')$$,'22023','Invalid focus date','infinite rejected');
select lives_ok($$select propose_focus_date('60000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000b401',now()+interval '1 day')$$,'propose to friend');
select lives_ok($$select propose_focus_date('60000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000b401',now()+interval '1 day')$$,'identical retry idempotent');
select is((select count(*) from focus_dates),1::bigint,'retry creates one row');
select throws_ok($$select propose_focus_date('60000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000b401',now()+interval '2 days')$$,'PT409','Focus date request changed','ID cannot change time');
select throws_ok($$select respond_focus_date('60000000-0000-0000-0000-000000000001',1,'accepted')$$,'PT409','Focus date response unavailable','proposer cannot self accept');
select throws_ok($$select respond_focus_date('60000000-0000-0000-0000-000000000001',1,'declined')$$,'PT409','Focus date response unavailable','proposer cannot decline');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000c401',true);
select is((select count(*) from focus_dates),0::bigint,'outsider cannot read');
select throws_ok($$select respond_focus_date('60000000-0000-0000-0000-000000000001',1,'cancelled')$$,'P0002','Focus date unavailable','outsider cannot cancel');
select throws_ok($$select propose_focus_date('60000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000b401',now()+interval '1 day')$$,'PT409','Focus date request changed','outsider cannot replay proposal');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000b401',true);
select is((select count(*) from focus_dates),1::bigint,'recipient sees invitation');
select lives_ok($$select respond_focus_date('60000000-0000-0000-0000-000000000001',1,'accepted')$$,'recipient accepts');
select is((select status from focus_dates),'accepted','confirmed accepted status');
select throws_ok($$select respond_focus_date('60000000-0000-0000-0000-000000000001',1,'cancelled')$$,'PT409','Focus date changed elsewhere','stale revision blocked');
select lives_ok($$select respond_focus_date('60000000-0000-0000-0000-000000000001',2,'cancelled')$$,'recipient can cancel accepted date');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000a401',true);
select lives_ok($$select propose_focus_date('60000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000b401',now()+interval '1 day')$$,'late creation retry harmless');
select is((select status from focus_dates),'cancelled','retry never revives cancelled date');
select throws_ok($$select respond_focus_date('60000000-0000-0000-0000-000000000001',3,'accepted')$$,'PT409','Focus date changed elsewhere','terminal state cannot revive');
select lives_ok($$select propose_focus_date('60000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-00000000b401',now()+interval '2 days')$$,'new request');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000b401',true);
select lives_ok($$select respond_focus_date('60000000-0000-0000-0000-000000000002',1,'declined')$$,'recipient can decline');
select is((select status from focus_dates where id='60000000-0000-0000-0000-000000000002'),'declined','decline final');
reset role;
-- An expired invitation cannot be accepted, even with the right revision.
insert into focus_dates(id,proposer_id,recipient_id,starts_at) values
 ('60000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-00000000a401','00000000-0000-0000-0000-00000000b401',now()-interval '1 second');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000b401',true);
select throws_ok($$select respond_focus_date('60000000-0000-0000-0000-000000000003',1,'accepted')$$,'PT409','Focus date response unavailable','expired cannot accept');
select lives_ok($$select propose_focus_date('60000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-00000000a401',now()+interval '3 days')$$,'reverse friend direction works');
reset role;
delete from friendships where requester_id='00000000-0000-0000-0000-00000000a401';
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000a401',true);
select throws_ok($$select respond_focus_date('60000000-0000-0000-0000-000000000004',1,'accepted')$$,'P0002','Friend unavailable','must still be friends to accept');
select lives_ok($$select respond_focus_date('60000000-0000-0000-0000-000000000004',1,'cancelled')$$,'can cancel after unfriending');
reset role;
insert into friendships(requester_id,addressee_id,status) values ('00000000-0000-0000-0000-00000000a401','00000000-0000-0000-0000-00000000b401','accepted');
insert into focus_dates(id,proposer_id,recipient_id,starts_at) select gen_random_uuid(),'00000000-0000-0000-0000-00000000a401','00000000-0000-0000-0000-00000000b401',now()+interval '1 day' from generate_series(1,10);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000a401',true);
select throws_ok($$select propose_focus_date(gen_random_uuid(),'00000000-0000-0000-0000-00000000b401',now()+interval '2 days')$$,'PT429','Upcoming date limit reached','upcoming cap enforced');
reset role;
update focus_dates set status='cancelled';
insert into focus_dates(id,proposer_id,recipient_id,starts_at,status) select gen_random_uuid(),'00000000-0000-0000-0000-00000000a401','00000000-0000-0000-0000-00000000b401',now()+interval '1 day','cancelled' from generate_series(1,10);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000a401',true);
select throws_ok($$select propose_focus_date(gen_random_uuid(),'00000000-0000-0000-0000-00000000b401',now()+interval '2 days')$$,'PT429','Daily proposal limit reached. Try tomorrow.','cancelling cannot bypass daily proposal limit');
reset role;
delete from auth.users where id='00000000-0000-0000-0000-00000000b401';
select is((select count(*) from focus_dates),0::bigint,'deleting either participant cascades dates');
select * from finish();
rollback;
